using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

public static class ActivadorResumenPropio
{
    private const string PruebaAcademica = " prueba academica ";

    private static readonly HashSet<string> MarcadoresDePrimeraPersona = new(StringComparer.Ordinal)
    {
        "mi", "mis", "tengo", "llevo", "voy", "cumplo", "soy", "estoy", "perdi", "gane", "saque", "quede"
    };

    private static readonly HashSet<string> TerminosDeDatosAcademicos = new(StringComparer.Ordinal)
    {
        "nota", "notas", "definitiva", "promedio", "corte", "falta", "faltas", "asistencia", "inasistencia",
        "inasistencias", "beca", "habilitar", "materia", "materias", "asignatura", "asignaturas", "perdida",
        "perdidas", "aprobe"
    };

    public static bool Activa(ContextoUsuario contexto, string pregunta)
    {
        if (contexto.Usuario.Rol != Rol.Estudiante)
        {
            return false;
        }

        var palabras = TokenizadorTexto.Valores(pregunta);
        return PideDatosAcademicos(palabras) && (palabras.Any(MarcadoresDePrimeraPersona.Contains) || MencionaSuNombre(contexto, palabras));
    }

    internal static bool PideDatosAcademicos(IReadOnlyList<string> palabras) =>
        palabras.Any(TerminosDeDatosAcademicos.Contains)
        || $" {string.Join(' ', palabras)} ".Contains(PruebaAcademica, StringComparison.Ordinal);

    private static bool MencionaSuNombre(ContextoUsuario contexto, IReadOnlyList<string> palabras) =>
        DetectorTerceros.MencionaNombreCompleto(contexto.Usuario.Id, string.Join(' ', palabras), contexto.Directorio);
}
using TutorFlow.Core.Academico;
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal sealed class LectorResumenPropio
{
    private readonly PoliticaAcceso _politicaAcceso;

    public LectorResumenPropio(PoliticaAcceso politicaAcceso)
    {
        _politicaAcceso = politicaAcceso;
    }

    public async Task<ResumenEntregado?> LeerAsync(
        ContextoUsuario contexto,
        string pregunta,
        IApiAcademica api,
        RegistroConsultas registro,
        CancellationToken cancellationToken)
    {
        var usuario = contexto.Usuario;
        if (!ActivadorResumenPropio.Activa(contexto, pregunta) || !PuedeLeerSusDatos(contexto))
        {
            return null;
        }

        var resumen = await ResumenesAcademicos.ResumirAsync(api, usuario.Id, cancellationToken);
        Registrar(contexto, resumen, registro);
        var entregado = FormateadorResumen.Resumir(resumen);
        registro.AgregarFuente(entregado.Texto);
        return entregado;
    }

    private bool PuedeLeerSusDatos(ContextoUsuario contexto) =>
        _politicaAcceso.EvaluarLecturaEstudiante(contexto.Usuario, contexto.Usuario.Id, contexto.Directorio).Permitido;

    private static void Registrar(ContextoUsuario contexto, ResumenEstudiante resumen, RegistroConsultas registro)
    {
        var id = contexto.Usuario.Id;
        var programaId = contexto.Directorio.Estudiantes.First(e => e.Id == id).ProgramaId;
        registro.Registrar(id, [RecursoConsultado.Notas, RecursoConsultado.Asistencia], new Cita(Textos.DocumentoDatosEstudiante, Textos.SeccionNotas));
        registro.RegistrarCita(new Cita(Textos.DocumentoDatosEstudiante, Textos.SeccionAsistencia));
        registro.RegistrarDatos(DatosLeidos.PorAsignatura(resumen, programaId, RecursoConsultado.Notas, RecursoConsultado.Asistencia));
    }
}
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Conocimiento;

public static class RaicesDeContenido
{
    private const int LongitudDeRaiz = 4;

    private static readonly HashSet<string> PalabrasVacias = new(StringComparer.Ordinal)
    {
        "cual", "cuales", "como", "cuando", "donde", "quien", "cuanto", "cuantos", "cuanta", "cuantas",
        "puedo", "tengo", "tiene", "tienen", "sobre", "para", "unos", "unas", "pero", "esta", "este", "esto",
        "dice", "dicen", "hacer", "hace", "debe", "puede", "pueden", "estoy", "estan", "dime", "dame", "muestra"
    };

    private static readonly HashSet<string> PalabrasGenericasDelCorpus = new(StringComparer.Ordinal)
    {
        "reglamento", "reglamentos", "documento", "documentos", "articulo", "articulos", "seccion", "secciones",
        "capitulo", "corporacion", "horizonte"
    };

    public static IEnumerable<string> De(string texto) =>
        NormalizadorTexto.Normalizar(texto)
            .Split(' ', StringSplitOptions.RemoveEmptyEntries)
            .Where(EsPalabraDeContenido)
            .Select(palabra => palabra[..LongitudDeRaiz])
            .Distinct(StringComparer.Ordinal);

    private static bool EsPalabraDeContenido(string palabra) =>
        palabra.Length >= LongitudDeRaiz
        && !PalabrasVacias.Contains(palabra)
        && !PalabrasGenericasDelCorpus.Contains(palabra);
}
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal sealed class RelevanciaPrevia
{
    private const string PalabraDelReglamentoDerogado = "2023";
    private const int LongitudDelAnio = 4;
    private const string PrimerSemestre = "1";
    private const string SegundoSemestre = "2";

    private static readonly HashSet<string> TerminosPropiosDelCoordinador = new(StringComparer.Ordinal)
    {
        "estudiante", "estudiantes", "programa", "programas"
    };

    private readonly PoliticaAcceso _politicaAcceso;
    private readonly int _relevanciaMinima;

    public RelevanciaPrevia(PoliticaAcceso politicaAcceso, int relevanciaMinima)
    {
        _politicaAcceso = politicaAcceso;
        _relevanciaMinima = relevanciaMinima;
    }

    public bool DebeResponderSinInformacion(ContextoUsuario contexto, string pregunta, IReadOnlyList<SeccionDocumento> secciones)
    {
        var palabras = TokenizadorTexto.Valores(pregunta);
        if (ActivadorResumenPropio.Activa(contexto, pregunta) || EsConsultaDeDatosDeCoordinador(contexto, palabras))
        {
            return PideOtroPeriodo(palabras);
        }

        return !palabras.Contains(PalabraDelReglamentoDerogado) && !HaySeccionRelevante(pregunta, secciones);
    }

    private bool EsConsultaDeDatosDeCoordinador(ContextoUsuario contexto, IReadOnlyList<string> palabras)
    {
        if (contexto.Usuario.Rol != Rol.Coordinador)
        {
            return false;
        }

        var programas = _politicaAcceso.ProgramasAutorizados(contexto.Usuario, contexto.Directorio);
        return programas.Count > 0
            && (PideTerminosDeDatos(palabras) || MencionaEstudianteDeSusProgramas(contexto, palabras, programas));
    }

    private static bool PideTerminosDeDatos(IReadOnlyList<string> palabras) =>
        palabras.Any(TerminosPropiosDelCoordinador.Contains) || ActivadorResumenPropio.PideDatosAcademicos(palabras);

    private static bool MencionaEstudianteDeSusProgramas(
        ContextoUsuario contexto,
        IReadOnlyList<string> palabras,
        IReadOnlyList<string> programas)
    {
        var propios = contexto.Directorio.Estudiantes.Where(e => programas.Contains(e.ProgramaId)).Select(e => e.Id).ToHashSet();
        return DetectorTerceros.PersonasMencionadas(string.Join(' ', palabras), contexto.Directorio).Any(propios.Contains);
    }

    private static bool PideOtroPeriodo(IReadOnlyList<string> palabras) =>
        palabras.Zip(palabras.Skip(1)).Any(par => EsPeriodo(par.First, par.Second) && $"{par.First}-{par.Second}" != Textos.Periodo);

    private static bool EsPeriodo(string anio, string semestre) =>
        anio.Length == LongitudDelAnio && anio.All(char.IsAsciiDigit) && (semestre == PrimerSemestre || semestre == SegundoSemestre);

    private bool HaySeccionRelevante(string pregunta, IReadOnlyList<SeccionDocumento> secciones)
    {
        var raices = RaicesDeContenido.De(pregunta).ToHashSet(StringComparer.Ordinal);
        var minimo = Math.Min(_relevanciaMinima, (raices.Count + 1) / 2);
        return raices.Count > 0 && secciones.Any(seccion => RaicesDeContenido.De($"{seccion.Titulo} {seccion.Texto}").Count(raices.Contains) >= minimo);
    }
}
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal sealed class CitasDeRespuesta
{
    private const int MaximoCitasDeRespaldo = 2;

    private readonly int _apoyoMinimo;

    public CitasDeRespuesta(int apoyoMinimo)
    {
        _apoyoMinimo = apoyoMinimo;
    }

    public IReadOnlyList<Cita> EscritasConApoyo(string texto, IReadOnlyList<SeccionDocumento> entregadas, IReadOnlyCollection<Cita> reglasDeDatos)
    {
        var apoyadas = SeccionesConApoyo(texto, entregadas).Select(CitaDe).ToHashSet();
        return [.. ExtractorCitas.De(texto).Where(cita => apoyadas.Contains(cita) || reglasDeDatos.Contains(cita))];
    }

    public IReadOnlyList<Cita> Respaldo(string texto, IReadOnlyList<SeccionDocumento> entregadas) =>
        [.. SeccionesConApoyo(texto, entregadas).Take(MaximoCitasDeRespaldo).Select(CitaDe)];

    private IEnumerable<SeccionDocumento> SeccionesConApoyo(string texto, IReadOnlyList<SeccionDocumento> entregadas)
    {
        var raicesDeLaRespuesta = RaicesDeContenido.De(ExtractorCitas.SinCitas(texto)).ToHashSet(StringComparer.Ordinal);
        return entregadas.Where(seccion => RaicesDeContenido.De($"{seccion.Titulo} {seccion.Texto}").Count(raicesDeLaRespuesta.Contains) >= _apoyoMinimo);
    }

    private static Cita CitaDe(SeccionDocumento seccion) => new(seccion.Documento, seccion.Seccion);
}
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

public sealed record PreguntaEntrada(string Pregunta, Usuario Usuario);

public sealed record RespuestaAsistente(
    string Respuesta,
    IReadOnlyList<Cita> Citas,
    bool UsoDatosEstudiante,
    int Tokens,
    decimal CostoUsd);

public enum TipoResultadoPregunta
{
    Respondida,
    Denegada,
    NoDisponible
}

public sealed record ResultadoPregunta(
    TipoResultadoPregunta Tipo,
    RespuestaAsistente? Respuesta,
    ResultadoAuditoria Auditoria,
    MotivoDenegacion? Motivo);

public sealed class PreguntarAsistente
{
    private readonly IApiAcademica _apiAcademica;
    private readonly IClienteLlm _clienteLlm;
    private readonly IBaseConocimiento _baseConocimiento;
    private readonly AuditorPeticiones _auditor;
    private readonly PoliticaAcceso _politicaAcceso;
    private readonly VerificadorSalida _verificadorSalida;
    private readonly LimitesAsistente _limites;
    private readonly ConfiguracionAsistente _configuracion;
    private readonly PresupuestoDiario _presupuesto;
    private readonly LectorResumenPropio _lectorResumen;
    private readonly RelevanciaPrevia _relevancia;
    private readonly CitasDeRespuesta _citasDeRespuesta;

    public PreguntarAsistente(
        IApiAcademica apiAcademica,
        IClienteLlm clienteLlm,
        IBaseConocimiento baseConocimiento,
        AuditorPeticiones auditor,
        PoliticaAcceso politicaAcceso,
        VerificadorSalida verificadorSalida,
        LimitesAsistente limites,
        ConfiguracionAsistente configuracion,
        PresupuestoDiario presupuesto)
    {
        _apiAcademica = apiAcademica;
        _clienteLlm = clienteLlm;
        _baseConocimiento = baseConocimiento;
        _auditor = auditor;
        _politicaAcceso = politicaAcceso;
        _verificadorSalida = verificadorSalida;
        _limites = limites;
        _configuracion = configuracion;
        _presupuesto = presupuesto;
        _lectorResumen = new LectorResumenPropio(politicaAcceso);
        _relevancia = new RelevanciaPrevia(politicaAcceso, configuracion.RelevanciaMinima);
        _citasDeRespuesta = new CitasDeRespuesta(configuracion.ApoyoMinimoRespaldo);
    }

    public async Task<ResultadoPregunta> EjecutarAsync(
        PreguntaEntrada entrada,
        string ipOrigen,
        string correlationId,
        CancellationToken cancellationToken)
    {
        var presupuestoApi = TimeSpan.FromSeconds(_limites.PresupuestoApiAcademicaSegundos);
        var api = new ApiAcademicaConPresupuesto(_apiAcademica, presupuestoApi);
        var directorio = await ConstructorDirectorio.ConstruirAsync(entrada.Usuario, api, _configuracion.CodigosAsignatura, cancellationToken);
        if (directorio is not null)
        {
            _auditor.RecordarPersonas(directorio);
        }

        var sesion = new SesionPregunta(entrada, ipOrigen, correlationId, api, directorio ?? ConstructorDirectorio.Vacio);
        var decision = Autorizar(sesion);
        return decision.Permitido
            ? await ResponderSiEsRelevanteAsync(sesion, cancellationToken)
            : Denegar(sesion, decision.Motivo, 0);
    }

    private async Task<ResultadoPregunta> ResponderSiEsRelevanteAsync(SesionPregunta sesion, CancellationToken cancellationToken)
    {
        var pregunta = sesion.Entrada.Pregunta;
        var contexto = new ContextoUsuario(sesion.Entrada.Usuario, sesion.Directorio);
        sesion.Secciones = _baseConocimiento.BuscarSecciones(ConsultaDeRecuperacion.DeTexto(pregunta), _limites.MaximoSeccionesRecuperadas);
        return _relevancia.DebeResponderSinInformacion(contexto, pregunta, sesion.Secciones)
            ? Responder(sesion, Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, usoDatos: false)
            : await ResponderConReservaAsync(sesion, cancellationToken);
    }

    private DecisionAcceso Autorizar(SesionPregunta sesion)
    {
        var identidad = _politicaAcceso.EvaluarIdentidad(sesion.Entrada.Usuario, sesion.Directorio);
        return identidad.Permitido
            ? _politicaAcceso.EvaluarPregunta(sesion.Entrada.Usuario, sesion.Entrada.Pregunta, sesion.Directorio)
            : identidad;
    }

    private async Task<ResultadoPregunta> ResponderConReservaAsync(SesionPregunta sesion, CancellationToken cancellationToken)
    {
        var reserva = _configuracion.ReservaPorPeticionUsd;
        if (!_presupuesto.TryReservar(reserva))
        {
            return NoDisponible(sesion, ResultadoAuditoria.Error);
        }

        try
        {
            return await ResponderConTimeoutAsync(sesion, cancellationToken);
        }
        finally
        {
            _presupuesto.Sustituir(reserva, CalculadoraCosto.Calcular(sesion.Uso.Valor, _configuracion.Precio));
        }
    }

    private async Task<ResultadoPregunta> ResponderConTimeoutAsync(SesionPregunta sesion, CancellationToken cancellationToken)
    {
        using var limite = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        limite.CancelAfter(TimeSpan.FromSeconds(_limites.TimeoutLlmSegundos));
        try
        {
            return await ResponderAsync(sesion, limite.Token);
        }
        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
        {
            throw new DependenciaNoDisponibleException("El tiempo total de la petición se agotó.");
        }
    }

    private async Task<ResultadoPregunta> ResponderAsync(SesionPregunta sesion, CancellationToken cancellationToken)
    {
        var usuario = sesion.Entrada.Usuario;
        var contexto = new ContextoUsuario(usuario, sesion.Directorio);
        var entrada = await PrepararEntradaAsync(sesion, contexto, cancellationToken);
        var conversacion = new ConversacionLlm(_clienteLlm, new HerramientasAsistente(sesion.Api, _politicaAcceso), _limites, sesion.Uso);
        var resultado = await conversacion.EjecutarAsync(contexto, entrada, sesion.Registro, cancellationToken);
        return resultado.Estado switch
        {
            EstadoConversacion.IdAjeno => Denegar(sesion, MotivoDenegacion.HerramientaIdAjeno, sesion.Uso.Valor.Total, resultado.IdSolicitado),
            EstadoConversacion.LimiteHerramientas => NoDisponible(sesion, ResultadoAuditoria.LimiteHerramientas),
            EstadoConversacion.Rechazada => Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.Error),
            _ => Completar(sesion, resultado.Texto ?? string.Empty, entrada)
        };
    }

    private async Task<EntradaConversacion> PrepararEntradaAsync(SesionPregunta sesion, ContextoUsuario contexto, CancellationToken cancellationToken)
    {
        var pregunta = sesion.Entrada.Pregunta;
        var resumen = await _lectorResumen.LeerAsync(contexto, pregunta, sesion.Api, sesion.Registro, cancellationToken);
        return new EntradaConversacion(pregunta, sesion.Secciones, resumen, ConstructorPrompts.PromptSistema(contexto.Usuario.Rol, _configuracion.MarcadorCanario));
    }

    private ResultadoPregunta Completar(SesionPregunta sesion, string texto, EntradaConversacion entrada)
    {
        if (texto.Trim() == Textos.SinInformacion)
        {
            return Responder(sesion, Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, usoDatos: false);
        }

        foreach (var seccion in entrada.Secciones)
        {
            sesion.Registro.AgregarFuente($"{seccion.Titulo}. {seccion.Texto}");
        }

        var directorio = sesion.Directorio;
        var autorizados = _politicaAcceso.IdsPersonasAutorizadas(sesion.Entrada.Usuario, directorio);
        var candidatas = _citasDeRespuesta.EscritasConApoyo(texto, entrada.Secciones, ReglasDeDatos(sesion, entrada));
        var verificada = _verificadorSalida.Verificar(sesion.Entrada.Usuario, texto, candidatas, autorizados, sesion.Registro.Fuentes, _baseConocimiento, directorio, Confidencial(entrada));
        return verificada.Resultado == ResultadoAuditoria.Respondida
            ? ResponderVerificada(sesion, verificada, entrada)
            : Responder(sesion, verificada.Respuesta, verificada.Citas, verificada.Resultado);
    }

    private ResultadoPregunta ResponderVerificada(SesionPregunta sesion, SalidaVerificada verificada, EntradaConversacion entrada)
    {
        var citasDeTextoFijo = Textos.CitasDeTextoFijo(verificada.Respuesta);
        if (citasDeTextoFijo is not null)
        {
            return Responder(sesion, verificada.Respuesta, citasDeTextoFijo, verificada.Resultado);
        }

        var respaldo = verificada.Citas.Count > 0 ? [] : _citasDeRespuesta.Respaldo(verificada.Respuesta, entrada.Secciones);
        if (verificada.Citas.Count + respaldo.Count == 0 && !sesion.Registro.UsoDatos)
        {
            return Responder(sesion, Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, usoDatos: false);
        }

        IReadOnlyList<Cita> citas = [.. verificada.Citas.Concat(respaldo).Concat(sesion.Registro.Citas).Distinct()];
        return Responder(sesion, verificada.Respuesta, citas, verificada.Resultado);
    }

    private static IReadOnlyCollection<Cita> ReglasDeDatos(SesionPregunta sesion, EntradaConversacion entrada) =>
        [.. (entrada.Resumen?.Reglas ?? []).Concat(sesion.Registro.Reglas)];

    private MaterialConfidencial Confidencial(EntradaConversacion entrada) =>
        new(_configuracion.MarcadorCanario, entrada.PromptSistema, HerramientasAsistente.NombresInternos);

    private ResultadoPregunta Responder(
        SesionPregunta sesion,
        string texto,
        IReadOnlyList<Cita> citas,
        ResultadoAuditoria resultado,
        bool? usoDatos = null)
    {
        var respuesta = new RespuestaAsistente(
            texto,
            citas,
            usoDatos ?? sesion.Registro.UsoDatos,
            sesion.Uso.Valor.Total,
            CalculadoraCosto.Calcular(sesion.Uso.Valor, _configuracion.Precio));
        Auditar(sesion, resultado, null, citas);
        return new ResultadoPregunta(TipoResultadoPregunta.Respondida, respuesta, resultado, null);
    }

    private ResultadoPregunta Denegar(SesionPregunta sesion, MotivoDenegacion? motivo, int tokens, string? idSolicitado = null)
    {
        var costo = CalculadoraCosto.Calcular(sesion.Uso.Valor, _configuracion.Precio);
        var citas = new[] { Textos.CitaNegativa() };
        var respuesta = new RespuestaAsistente(Textos.Negativa(sesion.Entrada.Usuario.Rol), citas, false, tokens, costo);
        Auditar(sesion, ResultadoAuditoria.Denegada, motivo, citas, idSolicitado);
        return new ResultadoPregunta(TipoResultadoPregunta.Denegada, respuesta, ResultadoAuditoria.Denegada, motivo);
    }

    private ResultadoPregunta NoDisponible(SesionPregunta sesion, ResultadoAuditoria resultado)
    {
        Auditar(sesion, resultado, null, []);
        return new ResultadoPregunta(TipoResultadoPregunta.NoDisponible, null, resultado, null);
    }

    private void Auditar(
        SesionPregunta sesion,
        ResultadoAuditoria resultado,
        MotivoDenegacion? motivo,
        IReadOnlyList<Cita> citas,
        string? idSolicitado = null)
    {
        var usuario = sesion.Entrada.Usuario;
        var pregunta = PreguntaAuditable(sesion);
        var costo = CalculadoraCosto.Calcular(sesion.Uso.Valor, _configuracion.Precio);
        var registro = sesion.Registro;
        _auditor.Registrar(new EventoAuditoria(
            _auditor.AhoraUtc, sesion.CorrelationId, sesion.IpOrigen, usuario.Rol, usuario.Id, pregunta, resultado, motivo,
            registro.Estudiantes, registro.Recursos, citas, sesion.Uso.Valor.Total, costo,
            sesion.Cronometro.ElapsedMilliseconds, _configuracion.Precio is null)
        {
            DatosConsultados = registro.DatosConsultados,
            IdSolicitado = idSolicitado
        });
    }

    private string PreguntaAuditable(SesionPregunta sesion)
    {
        var usuario = sesion.Entrada.Usuario;
        return _politicaAcceso.EvaluarIdentidad(usuario, sesion.Directorio).Permitido
            ? AuditorPeticiones.SanearPregunta(usuario, sesion.Entrada.Pregunta, sesion.Directorio)
            : _auditor.PreguntaSinIdentidad(sesion.Entrada.Pregunta);
    }
}

